function makeHashFromArray(a) {
  const t = a.map(e => e.value);
  return murmur.x64.hash128(t.join(''), 31);
}
console.log(makeHashFromArray(fingerpint));






// hàm Tạo Sign

function signature(str) {
    const md5 = crypto.createHash('md5');
    md5.update(str);
    return md5.digest('hex');
}


